#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 64

static long value[MAX_NODES];
static int next_idx[MAX_NODES];
static int head = -1;
static int used = 0;

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    head = -1;
    used = 0;

    for (int i = 1; i < argc && used < MAX_NODES; ++i) {
        long v = strtol(argv[i], NULL, 10);
        int idx = used++;
        value[idx] = v;
        next_idx[idx] = -1;

        if (head == -1 || value[head] > v) {
            next_idx[idx] = head;
            head = idx;
        } else {
            int prev = head;
            while (next_idx[prev] != -1 && value[next_idx[prev]] <= v) {
                prev = next_idx[prev];
            }
            next_idx[idx] = next_idx[prev];
            next_idx[prev] = idx;
        }
    }

    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) putchar(' ');
        printf("%ld", value[cur]);
        first = 0;
        cur = next_idx[cur];
    }
    putchar('\n');
    return 0;
}
